#include "flow/channel.hpp"
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <iterator>
#include <sstream>
#include <stdexcept>
#include <locale>
namespace {
std::string read(const std::filesystem::path& path){if(std::filesystem::file_size(path)>65536)throw std::invalid_argument("input exceeds 64 KiB");std::ifstream f(path);if(!f)throw std::runtime_error("input open");std::string text((std::istreambuf_iterator<char>(f)),{});if(f.bad())throw std::runtime_error("input read");return text;}
void write(const std::filesystem::path& path,const std::string& text){std::ofstream f(path);f<<text;f.close();if(!f)throw std::runtime_error("output write");}
void token(std::istream& in,const char* expected){std::string value;if(!(in>>value)||value!=expected)throw std::invalid_argument(std::string("expected ")+expected);}
flow::ChannelSettings parse(const std::string& text){std::istringstream in(text);in.imbue(std::locale::classic());flow::ChannelSettings s;token(in,"FLOW_CHANNEL");token(in,"1");token(in,"ports_m");in>>s.inlet_x_m>>s.outlet_x_m;token(in,"kernel_radius_m");in>>s.coupling.kernel_radius_m;token(in,"coupling_substeps");in>>s.coupling.coupling_substeps;token(in,"reaction_enabled");int flag=-1;in>>flag;if(flag!=0&&flag!=1)throw std::invalid_argument("reaction flag");s.coupling.reaction_enabled=flag==1;token(in,"gravity_m_s2");in>>s.coupling.gravity_m_s2.x>>s.coupling.gravity_m_s2.y>>s.coupling.gravity_m_s2.z;token(in,"release_count");int n=-1;in>>n;if(n<0||n>256)throw std::invalid_argument("release count");s.releases.clear();for(int i=0;i<n;++i){token(in,"release");flow::Release r;std::string id;in>>id;if(id.empty()||id.find_first_not_of("0123456789")!=std::string::npos)throw std::invalid_argument("unsigned release ID required");r.id=std::stoull(id);in>>r.requested_time_s>>r.diameter_m>>r.density_kg_m3>>r.y_m>>r.velocity_x_m_s;s.releases.push_back(r);}token(in,"end");std::string extra;if(in>>extra)throw std::invalid_argument("trailing channel input");return s;}
std::string quote(const std::string& s){std::string q="\"";for(char c:s){if(c=='"'||c=='\\')q+='\\';q+=c<' '?' ':c;}return q+'"';}
}
int main(int argc,char** argv){try{
if(argc!=4)throw std::invalid_argument("usage: flow_channel_run INPUT.flow INPUT.channel NEW_DIRECTORY");const auto c=flow::parse_contract(read(argv[1]));const auto input=read(argv[2]);const auto s=parse(input);auto state=flow::make_channel(c,s);const std::filesystem::path out=argv[3];if(!std::filesystem::create_directory(out))throw std::invalid_argument("output directory must be new");write(out/"input.flow",flow::serialize_contract(c));write(out/"input.channel",input);
std::ofstream history(out/"history.csv");history.imbue(std::locale::classic());history<<std::setprecision(17)<<"time_s,pending,due_waiting,active,exited,pending_mass_kg,active_mass_kg,exited_mass_kg,particle_mass_residual_kg,air_in_mass_kg,air_out_mass_kg,air_mass_residual_kg,inlet_probe_gauge_pa,outlet_probe_gauge_pa,test_volume_m3,buffer_volume_m3,gas_Jx_Ns,test_Jx_Ns,buffer_Jx_Ns,exchange_residual_Ns\n";
std::string error;double maxmass=0,maxair=0,maxexchange=0;const auto d=flow::validate(c);
try{while(state.coupled.air.accepted_steps<d.steps){auto r=flow::advance_channel(c,s,state);const auto& b=r.balance;maxmass=std::max(maxmass,b.particle_mass_residual_kg);maxair=std::max(maxair,b.air_mass_residual_kg);maxexchange=std::max(maxexchange,r.max_exchange_residual_n_s);history<<state.coupled.air.physical_time_s<<','<<b.pending<<','<<b.due_waiting<<','<<b.active<<','<<b.exited<<','<<b.pending_mass_kg<<','<<b.active_mass_kg<<','<<b.exited_mass_kg<<','<<b.particle_mass_residual_kg<<','<<state.air_in_mass_kg<<','<<state.air_out_mass_kg<<','<<b.air_mass_residual_kg<<','<<r.probe_inlet_gauge_pa<<','<<r.probe_outlet_gauge_pa<<','<<b.test_volume_m3<<','<<b.buffer_volume_m3<<','<<r.gas_impulse_n_s.x<<','<<r.test_reaction_impulse_n_s.x<<','<<r.buffer_reaction_impulse_n_s.x<<','<<r.max_exchange_residual_n_s<<'\n';if(!history)throw std::runtime_error("history write");}}catch(const std::exception& e){error=e.what();}
history.close();if(!history&&error.empty())error="history close";
std::ostringstream events;events.imbue(std::locale::classic());events<<std::setprecision(17)<<"id,status,requested_time_s,entry_time_s,crossing_time_s,removal_time_s,residence_time_s,mass_kg,diameter_m,density_kg_m3,last_x_m,last_y_m,last_vx_m_s\n";
for(const auto& t:state.records){const char* status=t.status==flow::TransitStatus::Pending?"pending":t.status==flow::TransitStatus::Active?"active":"exited";events<<t.request.id<<','<<status<<','<<t.request.requested_time_s<<','<<t.entry_time_s<<','<<t.crossing_time_s<<','<<t.removal_time_s<<','<<(t.status==flow::TransitStatus::Exited?t.crossing_time_s-t.entry_time_s:-1)<<','<<t.mass_kg<<','<<t.request.diameter_m<<','<<t.request.density_kg_m3<<','<<t.last_particle.position_m.x<<','<<t.last_particle.position_m.y<<','<<t.last_particle.velocity_m_s.x<<'\n';}write(out/"transits.csv",events.str());
const auto b=flow::channel_balance(c,s,state);std::ostringstream result;result.imbue(std::locale::classic());result<<std::setprecision(17)<<"{\"version\":"<<quote(flow::ChannelVersion)<<",\"passed\":"<<(error.empty()?"true":"false")<<",\"all_arrived\":"<<(b.exited==s.releases.size()?"true":"false")<<",\"accepted_steps\":"<<state.coupled.air.accepted_steps<<",\"physical_time_s\":"<<state.coupled.air.physical_time_s<<",\"pending\":"<<b.pending<<",\"active\":"<<b.active<<",\"exited\":"<<b.exited<<",\"exited_mass_kg\":"<<b.exited_mass_kg<<",\"max_particle_mass_residual_kg\":"<<maxmass<<",\"max_air_mass_residual_kg\":"<<maxair<<",\"max_exchange_residual_Ns\":"<<maxexchange<<",\"error\":"<<quote(error)<<"}\n";write(out/"result.json.tmp",result.str());std::filesystem::rename(out/"result.json.tmp",out/"result.json");std::cout<<(error.empty()?"PASS ":"FAILED ")<<out.string()<<'\n';return error.empty()?0:3;
}catch(const std::exception& e){std::cerr<<"CHANNEL_REJECTED: "<<e.what()<<'\n';return 2;}}
